func (r *inboxRuleResource) identityOf(m inboxRuleModel) any {
	if v := m.Identity.ValueString(); v != "" {
		return v
	}
	if v := m.ID.ValueString(); v != "" {
		return v
	}
	return m.Name.ValueString()
}

func (r *inboxRuleResource) refresh(ctx context.Context, identity any, m *inboxRuleModel, diags *diag.Diagnostics, reflected func(map[string]any) bool) bool {
	get := func(ctx context.Context) (map[string]any, bool, error) {
		res, gerr := r.client.EXO.GetInboxRule(ctx, exo.GetInboxRuleParams{Identity: identity})
		if gerr != nil {
			if isNotFound(gerr) {
				return nil, false, nil
			}
			return nil, false, gerr
		}
		o := firstObject(res.Value)
		return o, o != nil, nil
	}
	obj, present, err := resourcex.LoadUntil(ctx, consistency.Config{}, get, reflected)
	if err != nil {
		diags.AddError("Get-InboxRule failed", err.Error())
		return false
	}
	if !present {
		return false
	}
	readInboxRule(ctx, obj, m)
	return true
}

